    out = [row[:] for row in grid]

    # Four horizontal colored bars define four bands. In each band a gap in
    # the upper bar aligns with a vertical guide color on the lower bar. Fill
    # the column segment in the gap with the lower guide's color.
    bars = []
    for r, row in enumerate(grid):
        colors = {v for v in row if v != 0}
        if len(colors) == 1:
            color = next(iter(colors))
            if sum(v == color for v in row) >= 5:
                bars.append((r, row))

    for i in range(len(bars) - 1):
        upper_r, upper = bars[i]
        lower_r, lower = bars[i + 1]
        for c in range(w):
            if (0 < c < w - 1 and upper[c] == 0 and
